            project: None,
            tool: None,
            detail: "first detail".into(),
            updated_at: "2026-07-15T00:00:00Z".into(),
            state: crate::island::IslandAttentionState::Running,
        };
        let first_work_key = agent_view_key(&work);
        work.detail = "replacement detail".into();
        assert_ne!(first_work_key, agent_view_key(&work));

        let mut hit = HistorySearchHit {
            hit_id: "session-a:1".into(),
            session_id: "session-a".into(),
            session_title: "Session A".into(),
            role: "assistant".into(),
            excerpt: "first excerpt".into(),
            timestamp_ms: None,
            workspace_root: None,
            score: 1.0,
            match_kind: "fuzzy".into(),
        };
        let first_hit_key = history_view_key(&hit);
        hit.excerpt = "replacement excerpt".into();
        assert_ne!(first_hit_key, history_view_key(&hit));
    }

    #[test]
    fn recall_label_includes_role_and_bounded_excerpt() {
        let hit = HistorySearchHit {
            hit_id: "hit".into(),
            session_id: "session".into(),
            session_title: "Decision log".into(),
            role: "assistant".into(),
            excerpt: "水".repeat(220),
            timestamp_ms: None,
            workspace_root: None,
            score: 1.0,
            match_kind: "exact".into(),
        };
        let label = history_result_label(&hit);
        assert!(label.starts_with("Open assistant history match from Decision log: "));
        assert!(label.ends_with('…'));
        assert!(label.chars().count() < 230);
    }

    #[test]
    fn leaving_recall_retires_search_state() {
        assert!(recall_should_retire(IslandMode::Recall, IslandMode::Agent));
        assert!(recall_should_retire(IslandMode::Recall, IslandMode::Closed));
        assert!(!recall_should_retire(
            IslandMode::Recall,
            IslandMode::Recall
        ));
        assert!(!recall_should_retire(
            IslandMode::Sessions,
            IslandMode::Agent
        ));
    }

    #[test]
    fn scroll_follow_moves_only_when_selection_leaves_viewport() {
        assert_eq!(scroll_follow_target(20, 100, 10, 20), Some(10));
        assert_eq!(scroll_follow_target(20, 100, 100, 30), Some(30));
        assert_eq!(scroll_follow_target(20, 100, 40, 20), None);
    }

    #[test]
    fn idle_agent_prompt_rejects_composition_and_blank_text() {
        assert!(should_submit_agent_prompt(false, "hello"));
        assert!(!should_submit_agent_prompt(true, "hello"));
        assert!(!should_submit_agent_prompt(false, "  "));
    }

    #[test]
    fn modes_are_distinct_interactions() {
        assert_ne!(IslandMode::Agent, IslandMode::Sessions);
        assert_ne!(IslandMode::Sessions, IslandMode::Recall);
        assert_ne!(IslandMode::Agent, IslandMode::Recall);
    }

    #[test]
    fn bounded_session_results_keep_browse_small() {
        let items = (0..30)
            .map(|index| crate::island::IslandSession {
                id: format!("session-{index}"),
                title: format!("Session {index}"),
                project: None,
                cwd: "/tmp".into(),
                branch: None,
                origin: None,
                updated_at: format!("2026-07-15T00:{index:02}:00Z"),
                turn_count: 1,
                is_focused: index == 0,
                priority: if index == 0 {
                    crate::island::IslandPriority::Focused
                } else {
                    crate::island::IslandPriority::Background
                },
            })
            .collect::<Vec<_>>();
        let mut results = search_island("", &items);
        results.truncate(8);
        assert_eq!(results.len(), 8);
    }

    #[test]
    fn index_navigation_wraps() {
        assert_eq!(next_index(2, 3), 0);
        assert_eq!(previous_index(0, 3), 2);
        assert_eq!(next_index(0, 0), 0);
    }
}

