  86	fn scroll_follow_target(
  87	    view_top: i32,
  88	    view_height: i32,
  89	    item_top: i32,
  90	    item_height: i32,
  91	) -> Option<i32> {
  92	    if item_top < view_top {
  93	        Some(item_top)
  94	    } else {
  95	        let item_bottom = item_top.saturating_add(item_height);
  96	        let view_bottom = view_top.saturating_add(view_height);
  97	        (item_bottom > view_bottom).then_some(item_bottom.saturating_sub(view_height))
  98	    }
  99	}
