  51	fn bounded_accessible_excerpt(excerpt: &str) -> String {
  52	    const LIMIT: usize = 160;
  53	    let normalized = excerpt.split_whitespace().collect::<Vec<_>>().join(" ");
  54	    let mut chars = normalized.chars();
  55	    let prefix = chars.by_ref().take(LIMIT).collect::<String>();
  56	    if chars.next().is_some() {
  57	        format!("{prefix}…")
  58	    } else {
  59	        prefix
  60	    }
  61	}
