  70	        "transcript"
  71	    } else {
  72	        hit.role.trim()
  73	    };
  74	    let excerpt = bounded_accessible_excerpt(&hit.excerpt);
  75	    format!("Open {role} history match from {title}: {excerpt}")
  76	}
