 123	fn replacement_control_has_focus() -> bool {
 124	    web_sys::window()
 125	        .and_then(|window| window.document())
 126	        .and_then(|document| document.active_element())
 127	        .and_then(|element| element.dyn_into::<web_sys::HtmlElement>().ok())
 128	        .is_some_and(|element| {
 129	            element.is_connected()
 130	                && element.closest(".island-host").ok().flatten().is_none()
 131	                && element
 132	                    .matches(
 133	                        "button, input, textarea, select, a[href], [tabindex]:not([tabindex='-1'])",
 134	                    )
 135	                    .unwrap_or(false)
 136	        })
 137	}
