 434	#[component]
 435	pub fn DynamicIsland(
 436	    daemon: Daemon,
 437	    mode: RwSignal<IslandMode>,
 438	    focus_request: RwSignal<u64>,
 439	    on_open: Callback<IslandMode>,
 440	) -> impl IntoView {
 441	    let session_query = RwSignal::new(String::new());
 442	    let history_query = RwSignal::new(String::new());
 443	    let session_selected = RwSignal::new(0usize);
 444	    let history_selected = RwSignal::new(0usize);
 445	    let agent_selected = RwSignal::new(0usize);
 446	    let history_debounce = RwSignal::new(0u64);
 447	    let previous_mode = RwSignal::new(IslandMode::Closed);
 448	    let previous_focus = StoredValue::new_local(None::<web_sys::HtmlElement>);
 449	    let last_focus_request = RwSignal::new(0u64);
 450	    let session_input_ref: NodeRef<leptos::html::Input> = NodeRef::new();
 451	    let history_input_ref: NodeRef<leptos::html::Input> = NodeRef::new();
 452	    let session_results_ref: NodeRef<leptos::html::Div> = NodeRef::new();
 453	    let history_results_ref: NodeRef<leptos::html::Div> = NodeRef::new();
 454	    let chip_ref: NodeRef<leptos::html::Button> = NodeRef::new();
 455	    let stage_ref: NodeRef<leptos::html::Section> = NodeRef::new();
 456	
 457	    #[cfg(target_arch = "wasm32")]
 458	    let attention_interval = {
 459	        let daemon = daemon.clone();
 460	        send_wrapper::SendWrapper::new(gloo_timers::callback::Interval::new(3_000, move || {
 461	            daemon.fetch_attention();
 462	        }))
 463	    };
 464	    #[cfg(target_arch = "wasm32")]
 465	    on_cleanup(move || drop(attention_interval));
 466	
 467	    let session_list = daemon.session_list;
 468	    let request_list = daemon.request_list;
 469	    let projects = daemon.projects;
 470	    let focused_id = daemon.session_id;
 471	    let active_request_id = daemon.active_turn_id;
 472	    let focused_permissions = daemon.pending_permissions;
 473	    let history_results = daemon.history_results;
 474	    let history_searching = daemon.history_searching;
 475	    let history_error = daemon.history_error;
 476	    let daemon_value = StoredValue::new(daemon.clone());
 477	
 478	    daemon.fetch_sessions();
 479	    daemon.fetch_projects();
 480	    daemon.fetch_attention();
 481	
 482	    let sessions = Memo::new(move |_| {
 483	        derive_island_sessions(
 484	            &session_list.get(),
 485	            &projects.get(),
 486	            focused_id.get().as_deref(),
 487	        )
 488	    });
 489	    let attention_items = Memo::new(move |_| {
 490	        derive_attention_items(
 491	            &request_list.get(),
 492	            &sessions.get(),
 493	            focused_id.get().as_deref(),
 494	            active_request_id.get().as_deref(),
 495	            &focused_permissions.get(),
 496	        )
 497	    });
 498	    let attention_counts = Memo::new(move |_| compact_attention_counts(&attention_items.get()));
 499	    let session_results = Memo::new(move |_| {
 500	        let mut matches = search_island(&session_query.get(), &sessions.get());
 501	        matches.truncate(if session_query.get().trim().is_empty() {
 502	            8
 503	        } else {
 504	            20
 505	        });
 506	        matches
 507	    });
 508	
 509	    Effect::new(move |_| {
 510	        let len = session_results.get().len();
 511	        if len == 0 || session_selected.get() >= len {
 512	            session_selected.set(0);
 513	        }
 514	    });
 515	    Effect::new(move |_| {
 516	        let len = history_results.get().len();
 517	        if len == 0 || history_selected.get() >= len {
 518	            history_selected.set(0);
 519	        }
 520	    });
 521	
 522	    Effect::new(move |_| {
 523	        let next = mode.get();
 524	        let request = focus_request.get();
 525	        let previous = previous_mode.get_untracked();
 526	        let previous_request = last_focus_request.get_untracked();
 527	        if recall_should_retire(previous, next) {
 528	            history_debounce.update(|generation| *generation = generation.wrapping_add(1));
 529	            history_query.set(String::new());
 530	            history_selected.set(0);
 531	            daemon_value.get_value().invalidate_history_search();
 532	        }
 533	        if next != IslandMode::Closed && previous == IslandMode::Closed {
 534	            previous_focus.set_value(
 535	                web_sys::window()
 536	                    .and_then(|window| window.document())
 537	                    .and_then(|document| document.active_element())
 538	                    .and_then(|element| element.dyn_into::<web_sys::HtmlElement>().ok()),
 539	            );
 540	            let daemon = daemon_value.get_value();
 541	            daemon.fetch_sessions();
 542	            daemon.fetch_projects();
 543	            daemon.fetch_attention();
 544	        }
 545	        let should_focus = next != IslandMode::Closed
 546	            && (previous == IslandMode::Closed || next != previous || request != previous_request);
 547	        if should_focus {
 548	            request_animation_frame(move || match next {
 549	                IslandMode::Sessions => {
 550	                    if let Some(input) = session_input_ref.get() {
 551	                        let _ = input.focus();
 552	                        input.select();
 553	                    }
 554	                }
 555	                IslandMode::Recall => {
