 625	            });
 626	        }
 627	    });
 628	    Effect::new(move |_| {
 629	        if mode.get() != IslandMode::Recall {
 630	            return;
 720	                                .switch_session(hit.session_id.clone(), hit.session_title.clone());
 721	                            close.run(());
