2922	    /// Invalidate any in-flight/debounced Recall query immediately. Input
2923	    /// handlers call this before their debounce so stale query-A results cannot
2924	    /// become actionable while query B is already visible in the field.
2925	    pub fn invalidate_history_search(&self) {
2926	        self.history_search_generation
2927	            .update(|generation| *generation = generation.wrapping_add(1));
2928	        self.history_results.set(Vec::new());
2929	        self.history_error.set(None);
2930	        self.history_searching.set(false);
2931	    }
