2933	    /// Search persisted user/assistant transcript text through the daemon-owned
2934	    /// Recall endpoint. Empty queries clear the view locally. Generation checks
2935	    /// ensure an older, slower request can never replace newer results.
2936	    pub fn search_history(&self, query: String) {
2937	        let query = query.trim().to_string();
2938	        let generation = self
2939	            .history_search_generation
2940	            .get_untracked()
2941	            .wrapping_add(1);
2942	        self.history_search_generation.set(generation);
2943	        if query.is_empty() {
2944	            self.history_results.set(Vec::new());
2945	            self.history_error.set(None);
2946	            self.history_searching.set(false);
2947	            return;
2948	        }
2949	
2950	        self.history_searching.set(true);
2951	        self.history_error.set(None);
2952	        self.history_results.set(Vec::new());
2953	        let base = self.url.get_untracked().trim_end_matches('/').to_string();
2954	        let encoded = js_sys::encode_uri_component(&query)
2955	            .as_string()
2956	            .unwrap_or_else(|| query.clone());
2957	        let url = format!("{base}/v1/agent/history/search?q={encoded}&limit=20");
2958	        let active_generation = self.history_search_generation;
2959	        let history_results = self.history_results;
2960	        let history_searching = self.history_searching;
2961	        let history_error = self.history_error;
2962	        spawn_local(async move {
2963	            let result = match Request::get(&url).send().await {
2964	                Ok(response) => match response.json::<HistorySearchResponse>().await {
2965	                    Ok(payload) if payload.ok => Ok(payload.hits),
2966	                    Ok(payload) => Err(payload
2967	                        .error
2968	                        .filter(|error| !error.trim().is_empty())
2969	                        .unwrap_or_else(|| "History search failed".to_string())),
2970	                    Err(error) => Err(format!("History response was unreadable: {error}")),
2971	                },
2972	                Err(error) => Err(format!("History search is unavailable: {error}")),
2973	            };
2974	            if active_generation.get_untracked() != generation {
2975	                return;
2976	            }
2977	            match result {
2978	                Ok(hits) => {
2979	                    history_results.set(hits);
2980	                    history_error.set(None);
2981	                }
2982	                Err(error) => {
2983	                    history_results.set(Vec::new());
2984	                    history_error.set(Some(error));
2985	                }
2986	            }
2987	            history_searching.set(false);
2988	        });
2989	    }
